import { Composio } from "@composio/core";
import { VercelProvider } from "@composio/vercel";
import { generateText } from "ai";
import { openai } from "@ai-sdk/openai";
import * as fs from "fs";

async function main() {
  // Read trial_id from /logs/trial_id
  const trialId = fs.readFileSync("/logs/trial_id", "utf-8").trim();
  console.log(`Trial ID: ${trialId}`);

  // Initialize Composio with VercelProvider
  const composio = new Composio({
    apiKey: process.env.COMPOSIO_API_KEY,
    provider: new VercelProvider(),
  });

  // Get tools for the user zealt-user01
  const tools = await composio.tools.get("zealt-user01", {
    toolkits: ["github", "slack"],
  });
  console.log(`Available tools: ${Object.keys(tools).join(", ")}`);

  // Generate text using Vercel AI SDK with chat model
  const result = await generateText({
    model: openai.chat("gpt-4o-mini"),
    tools: tools,
    prompt: `You are an agent that fetches GitHub user information and posts summaries to Slack.

Your task:
1. Fetch the GitHub profile of the user 'composiohq' using the GITHUB_GET_A_USER tool.
2. Extract the user's 'bio' and 'public_repos' count from the response.
3. Post a message to the Slack channel named 'agent-results-${trialId}' with the summary: "User composiohq has {public_repos} repos. Bio: {bio}"

Please perform these steps in order and provide a summary of what you accomplished.`,
  });

  console.log("\n=== Agent Result ===");
  console.log(result.text);
  console.log("\n=== Tool Calls ===");
  console.log(JSON.stringify(result.toolCalls, null, 2));
  console.log("\n=== Tool Results ===");
  console.log(JSON.stringify(result.toolResults, null, 2));
}

main().catch((error) => {
  console.error("Error:", error);
  process.exit(1);
});

